# Original flash-style illustrations (drawn for this site; not the studio's work).
K='#121212';R='#C42021';G='#2E7D4F';Y='#F2B705';B='#25456B';S='#F1B98C';P='#E9E0C9'
def o(d,fill,w=5): return f'<path d="{d}" fill="{fill}" stroke="{K}" stroke-width="{w}" stroke-linejoin="round" stroke-linecap="round"/>'
ART={
'boltpen': 'Lightning pen',
'heart':'Heart & banner','dagger':'Dagger','swallow':'Swallow','rose':'Rose','anchor':'Anchor',
'star':'Nautical star','skull':'Skull','moon':'Moon & stars','web':'Spiderweb','flame':'Flame','eye':'All-seeing eye',
}
def sym(name):
    if name=='boltpen': body=(o("M100 18 L128 70 L118 150 L100 178 L82 150 L72 70 Z",B)+o("M100 178 L100 222",'none',4)+
        o("M88 96 L112 96 L100 150 Z",P,4)+o("M136 40 L112 98 L132 98 L104 160 L124 104 L104 104 L120 40 Z",Y,4))
    elif name=='heart': body=(o("M100 205 C40 160 25 120 35 88 C45 55 85 50 100 82 C115 50 155 55 165 88 C175 120 160 160 100 205 Z",R)+
        o("M20 120 L60 112 L60 142 L20 150 L32 135 Z",P,4)+o("M180 120 L140 112 L140 142 L180 150 L168 135 Z",P,4)+
        o("M55 108 Q100 96 145 108 L145 140 Q100 128 55 140 Z",P,4)+o("M62 70 Q70 58 82 60",'none',4))
    elif name=='dagger': body=(o("M100 20 L114 60 L112 150 L100 170 L88 150 L86 60 Z",P)+o("M100 40 L100 150",'none',3)+
        o("M60 150 L140 150 L140 164 L60 164 Z",Y)+o("M92 164 L108 164 L108 205 L92 205 Z",R)+o("M100 205 m-14 0 a14 14 0 1 0 28 0 a14 14 0 1 0 -28 0",Y))
    elif name=='swallow': body=(o("M40 70 C70 70 95 85 110 110 C130 90 165 85 185 95 C160 105 145 120 135 140 C150 160 170 175 180 200 C150 190 125 175 112 160 C95 175 70 182 45 178 C65 165 80 150 88 130 C70 120 50 100 40 70 Z",B)+
        o("M88 130 C95 150 110 158 112 160 C118 140 124 128 135 140 C120 120 105 118 88 130 Z",R,4)+o("M60 85 m-5 0 a5 5 0 1 0 10 0 a5 5 0 1 0 -10 0",K,2))
    elif name=='rose': body=(o("M100 60 C140 55 160 85 150 115 C140 145 110 150 100 150 C90 150 60 145 50 115 C40 85 60 55 100 60 Z",R)+
        o("M100 80 C120 80 128 98 118 112 C108 124 90 120 84 108 C78 94 88 82 100 88",'none',4)+o("M100 150 L104 220",'none',5)+
        o("M102 180 C130 160 160 170 165 185 C140 195 120 190 102 180 Z",G,4)+o("M102 195 C75 178 45 185 40 200 C65 210 85 205 102 195 Z",G,4))
    elif name=='anchor': body=(o("M100 30 m-16 0 a16 16 0 1 0 32 0 a16 16 0 1 0 -32 0",P)+o("M93 46 L107 46 L107 195 L93 195 Z",B)+
        o("M65 70 L135 70 L135 84 L65 84 Z",B,4)+o("M40 150 C45 195 80 210 100 210 C120 210 155 195 160 150 L180 160 L150 120 L140 160 C135 180 120 190 100 190 C80 190 65 180 60 160 L50 120 L20 160 Z",B)+
        o("M40 110 C70 120 130 120 160 110",'none',4))
    elif name=='star': body=(o("M100 15 L125 88 L195 100 L125 112 L100 205 L75 112 L5 100 L75 88 Z",'none')+
        o("M100 15 L100 100 L75 88 Z",R,4)+o("M195 100 L100 100 L125 88 Z",K,4)+o("M100 205 L100 100 L125 112 Z",R,4)+o("M5 100 L100 100 L75 112 Z",K,4))
    elif name=='skull': body=(o("M100 30 C150 30 170 65 168 100 C166 130 150 140 145 150 L145 185 L55 185 L55 150 C50 140 34 130 32 100 C30 65 50 30 100 30 Z",P)+
        o("M65 95 C65 80 92 80 90 100 C88 118 66 118 65 95 Z",K,3)+o("M110 100 C108 80 135 80 135 95 C134 118 112 118 110 100 Z",K,3)+
        o("M100 120 L92 140 L108 140 Z",K,3)+o("M72 165 L72 185 M88 165 L88 185 M112 165 L112 185 M128 165 L128 185",'none',4)+o("M40 40 L58 60 M160 40 L142 60",'none',4))
    elif name=='moon': body=(o("M120 30 C70 30 40 75 45 120 C50 170 95 200 140 190 C100 175 80 140 85 105 C90 70 110 45 120 30 Z",Y)+
        o("M150 70 L156 86 L172 88 L158 98 L162 114 L150 104 L138 114 L142 98 L128 88 L144 86 Z",R,4)+o("M160 140 L164 150 L174 152 L166 158 L168 168 L160 162 L152 168 L154 158 L146 152 L156 150 Z",P,3))
    elif name=='web': body=(o("M20 20 L180 20 L180 180",'none',4)+o("M20 20 L180 180 M20 20 L100 190 M20 20 L190 100",'none',4)+
        o("M60 20 Q70 50 40 60 M110 20 Q120 70 60 110 M160 20 Q165 100 100 160 M180 60 Q130 80 120 120 M180 120 Q150 130 145 150",'none',4)+
        o("M140 150 m-10 0 a10 10 0 1 0 20 0 a10 10 0 1 0 -20 0",K,2)+o("M140 160 L140 200",'none',2))
    elif name=='flame': body=(o("M100 210 C50 210 35 170 45 135 C55 105 75 95 70 60 C95 75 105 95 100 120 C115 105 115 80 110 30 C150 60 170 110 160 150 C152 190 130 210 100 210 Z",R)+
        o("M100 205 C75 205 68 180 75 160 C82 142 95 140 95 120 C115 135 130 160 125 180 C120 198 112 205 100 205 Z",Y,4))
    elif name=='eye': body=(o("M100 25 L185 185 L15 185 Z",Y)+o("M50 130 Q100 85 150 130 Q100 175 50 130 Z",P,4)+
        o("M100 130 m-18 0 a18 18 0 1 0 36 0 a18 18 0 1 0 -36 0",B,4)+o("M100 130 m-7 0 a7 7 0 1 0 14 0 a7 7 0 1 0 -14 0",K,2)+o("M100 10 L100 0 M70 20 L62 10 M130 20 L138 10",'none',4))
    return f'<symbol id="a-{name}" viewBox="0 0 200 230">{body}</symbol>'
def sprite(names): return '<svg width="0" height="0" style="position:absolute" aria-hidden="true">'+''.join(sym(n) for n in names)+'</svg>'
def use(name,cls='art'): return f'<svg class="{cls}" viewBox="0 0 200 230" aria-hidden="true" focusable="false"><use href="#a-{name}"/></svg>'
